package storage

import (
	_ "embed"
	"encoding/json"
	"strings"
	"sync"
)

// standard_stub_restricted_picklists.json is generated by
// scripts/generate-standard-stub-restricted-picklists.py from the owned P0
// REST describes (plain Developer org, API 62.0 and 67.0). Do not edit it.
//
//go:embed standard_stub_restricted_picklists.json
var standardStubRestrictedPicklistsData []byte

type standardStubRestrictedPicklist struct {
	Type   string `json:"type"`
	Values []struct {
		Value   string `json:"value"`
		Label   string `json:"label"`
		Active  bool   `json:"active"`
		Default bool   `json:"default"`
	} `json:"values"`
}

var standardStubRestrictedPicklists = sync.OnceValue(func() map[string]map[string]standardStubRestrictedPicklist {
	var doc struct {
		Objects map[string]map[string]standardStubRestrictedPicklist `json:"objects"`
	}
	if err := json.Unmarshal(standardStubRestrictedPicklistsData, &doc); err != nil {
		panic("decode standard stub restricted picklists: " + err.Error())
	}
	out := make(map[string]map[string]standardStubRestrictedPicklist, len(doc.Objects))
	for object, fields := range doc.Objects {
		lowered := make(map[string]standardStubRestrictedPicklist, len(fields))
		for name, field := range fields {
			lowered[strings.ToLower(name)] = field
		}
		out[strings.ToLower(object)] = lowered
	}
	return out
})

// standardStubRestrictedPicklistFields lists the native restricted picklists
// of an object whose generated stub overlay types them as String.
func standardStubRestrictedPicklistFields(objectName string) map[string]standardStubRestrictedPicklist {
	stubs, ok := standardSObjectStubFieldsFor(objectName)
	if !ok {
		return nil
	}
	native := standardStubRestrictedPicklists()[strings.ToLower(objectName)]
	if len(native) == 0 {
		return nil
	}
	var out map[string]standardStubRestrictedPicklist
	for name, stub := range stubs {
		entry, ok := native[strings.ToLower(name)]
		if !ok || stub.Type != FieldString {
			continue
		}
		if out == nil {
			out = make(map[string]standardStubRestrictedPicklist)
		}
		out[name] = entry
	}
	return out
}

// standardStubStringPicklist reports whether a definition field still holds
// the stub String shape of a native picklist. Formula, typed or configured
// fields keep their own shape.
func standardStubStringPicklist(field Field) bool {
	display := strings.TrimSpace(field.DisplayType)
	return field.Type == FieldString && (display == "" || strings.EqualFold(display, "STRING")) &&
		strings.TrimSpace(field.Formula) == "" && !field.PicklistValuesConfigured
}

// applyStandardStubRestrictedPicklists gives stub String fields the native
// picklist type, the restrictedPicklist facet and, where P0 holds a complete
// list, its values. An Apex picklist is a String, so String-typed Apex access
// stays legal. The restriction carries catalog provenance: DML enforcement
// stays limited to fields with captured insert and update rows.
func applyStandardStubRestrictedPicklists(definition *ObjectDefinition) {
	if definition == nil || definition.Fields == nil {
		return
	}
	for stubName, native := range standardStubRestrictedPicklistFields(definition.APIName) {
		name, exists := ResolveFieldName(*definition, "", stubName)
		if !exists {
			continue
		}
		field := definition.Fields[name]
		if !standardStubStringPicklist(field) {
			continue
		}
		field.Type, field.DisplayType = FieldPicklist, "PICKLIST"
		if strings.EqualFold(native.Type, "multipicklist") {
			field.Type, field.DisplayType = FieldMultiPicklist, "MULTIPICKLIST"
		}
		if !field.RestrictedPicklist {
			field.RestrictedPicklist = true
			field.RestrictedPicklistFromCatalog = true
		}
		if len(field.PicklistValues) == 0 && len(native.Values) != 0 {
			field.PicklistValues = make([]PicklistValue, len(native.Values))
			for i, value := range native.Values {
				field.PicklistValues[i] = PicklistValue{Value: value.Value, Label: value.Label, Active: value.Active, Default: value.Default}
			}
		}
		definition.Fields[name] = field
	}
}

// standardStubRestrictedPicklistsNeedRepair finds persisted definitions that
// still carry the stub String shape of a native restricted picklist.
func standardStubRestrictedPicklistsNeedRepair(definition ObjectDefinition, fields []string) bool {
	for _, stubName := range fields {
		name, exists := ResolveFieldName(definition, "", stubName)
		if exists && standardStubStringPicklist(definition.Fields[name]) {
			return true
		}
	}
	return false
}
